import manifest from "@/content/image-manifest.json";
import PriorityImage from "./PriorityImage";
import { ImageMarkup } from "./responsive-image-markup";

// Drop-in replacement for next/image for photos generated by
// scripts/optimize-images.mjs. The site is a static export with
// `images.unoptimized`, so next/image can't produce responsive variants;
// this component reads the build-time manifest and emits srcset (WebP) or a
// <picture> with an AVIF source.
//
// Supports the next/image props used in this codebase:
//   src, alt, fill, sizes, width, height, preload, priority, className, style.
// `preload`/`priority` images render through PriorityImage (client), which
// adds a responsive preload; all others are lazy-loaded.
// Images not in the manifest render as a plain <img> with the given src.

const variant = (src, w, ext) => src.replace(/\.webp$/, `-${w}.${ext}`);
const srcSetFor = (src, widths, ext) => widths.map((w) => `${variant(src, w, ext)} ${w}w`).join(", ");

export default function ResponsiveImage({
  src,
  alt = "",
  fill = false,
  sizes,
  width,
  height,
  preload = false,
  priority = false,
  className,
  style,
}) {
  const entry = manifest[src];
  const props = {
    src,
    alt,
    fill,
    width: width ?? entry?.width,
    height: height ?? entry?.height,
    sizes: sizes ?? (fill ? "100vw" : undefined),
    webpSet: entry ? srcSetFor(src, entry.widths, "webp") : undefined,
    avifSet: entry?.avif ? srcSetFor(src, entry.widths, "avif") : undefined,
    className,
    style,
  };
  if (preload || priority) return <PriorityImage {...props} />;
  return <ImageMarkup {...props} eager={false} />;
}
